.container {
    display: flex;
    height: auto;
    min-height: 100vh;
    justify-content: center;
    flex-direction: row;
}
.left-container {
    width: 50%;
    position: relative;
    display: flex;
    justify-content: space-evenly;
    flex-direction: column;
}
.login-button{
    padding: 16px;
}
.empty {
    height: 10%;
}

.left-container-data {
    display: flex;
    align-items: center;
    flex-direction: column;
    justify-content: space-evenly;
}
.input{
    border-radius: 4px;
    border: 1px solid var(--surface-steel-200, #bcc3cd);
    background: var(--surface-gray-0, #fff);
    padding: 16px;
    
}
#forgotPassword{
    display: flex;
    justify-content: flex-end;
    text-decoration: none;
    color:#095192;
    font-weight: 600;
}
#api, .title-row {
    width: 60%;
    position: relative;
}


#logo-image {
    background-image: url(data:image/svg+xml;base64,);
    background-repeat: no-repeat;
    background-size: contain;
    height: 68px;
    width: 154px;
}
.welcome-text {
    color: #212121;
    font-size: 32px;
    font-weight: 600;
}

.enter-details-label {
    color: #424242;
    font-size: 14px;
    font-weight: 400;
    line-height: 2em;
}
#api, .title-row {
    width: 60%;
    position: relative;
}

.input-password{
    border: 1px solid var(--surface-steel-200, #bcc3cd);
    background: var(--surface-gray-0, #fff);
    border-radius: 4px;
}
.allyiq-help-text {
    color: var(--text-gray, #767676);
    font-size: 14px;
    font-weight: 400;
    margin: 0px 40px 10px 40px;
}
.right-container {
    width: 50%;
    padding: 10px;
}
#signin-image {
    background-image: url(data:image/svg+xml;base64,);
    background-repeat: no-repeat;
    background-size: contain;
    height: 100%;
    background-position: center;
    margin-bottom: 20px;
}